# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student


def _require_emails(students: List[Student]) -> None:
    if not students:
        raise ValueError("no students for contact sheet")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email for {name}")


def _sort_key(student: Student):
    name = student.display_name.casefold()
    return (name, student.student_id)


def _widest(values: List[str]) -> int:
    return max(len(value) for value in values)


def _align(students: List[Student]) -> List[str]:
    names = [item.display_name for item in students]
    wide_name = _widest(names)
    wide_sect = _widest([item.section for item in students])
    return [
        f"{name:<{wide_name}}  "
        f"{item.section:<{wide_sect}}  {item.email}"
        for name, item in zip(names, students)
    ]


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _require_emails(students)
    return _align(sorted(students, key=_sort_key))

