# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make_student(last, first, section, email="a@x.org"):
    ident = "id" + last
    return Student(ident, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Young", "Zed", "B", "zed@x.org"),
            make_student("Adams", "Amy", "Nort", "amy@x.io")
        ]

    def test_rows_are_sorted_by_name(self):
        rows = contact_rows(self.students)
        self.assertTrue(rows[0].startswith("Adams, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_line_up(self):
        rows = contact_rows(self.students)
        first, second = rows
        self.assertEqual(
            first.index("amy@"), second.index("zed@")
        )
        self.assertEqual(
            first.index("Nort"), second.index("B ")
        )

    def test_row_holds_all_three_fields(self):
        row = contact_rows(self.students)[0]
        expected = ["Adams,", "Amy", "Nort", "amy@x.io"]
        self.assertEqual(row.split(), expected)

    def test_missing_email_names_the_student(self):
        extra = make_student("Lopez", "Ana", "A", None)
        self.students.append(extra)
        with self.assertRaisesRegex(ValueError, "Lopez"):
            contact_rows(self.students)

    def test_blank_email_is_missing(self):
        blank = make_student("Lopez", "Ana", "A", "")
        with self.assertRaisesRegex(ValueError, "Lopez"):
            contact_rows([blank])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
